// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Badge } from "@/registry/erbium/ui/badge";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Badge } from \"@/registry/erbium/ui/badge\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Badge>) => <Badge {...args} />;\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/badge-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import VariantsExample from "./variants/variants";

const VariantsSource = "import { Badge } from \"@/registry/erbium/ui/badge\";\n\nconst Example = () => (\n  <div className=\"flex gap-related\">\n    {(\n      [\n        \"default\",\n        \"secondary\",\n        \"info\",\n        \"success\",\n        \"warning\",\n        \"error\",\n        \"ghost-error\",\n        \"ghost-success\",\n        \"ghost-warning\",\n        \"ghost-info\",\n        \"tag-gray\",\n        \"tag-red\",\n        \"tag-orange\",\n        \"tag-yellow\",\n        \"tag-green\",\n        \"tag-cyan\",\n        \"tag-blue\",\n        \"tag-purple\",\n        \"tag-magenta\",\n        \"outline\",\n      ] as const\n    ).map((variant) => (\n      <Badge key={variant} variant={variant}>\n        {variant}\n      </Badge>\n    ))}\n  </div>\n);\n\nexport default Example;\n";

import LinkExample from "./variants/link";

const LinkSource = "import { BadgeAsLink } from \"../examples/badge-link\";\n\nconst Example = () => <BadgeAsLink />;\n\nexport default Example;\n";

import WithIconExample from "./variants/with-icon";

const WithIconSource = "import { BadgeWithIconLeft } from \"../examples/badge-icon\";\n\nconst Example = () => <BadgeWithIconLeft />;\n\nexport default Example;\n";

import WithSpinnerExample from "./variants/with-spinner";

const WithSpinnerSource = "import { BadgeWithSpinner } from \"../examples/badge-spinner\";\n\nconst Example = () => <BadgeWithSpinner />;\n\nexport default Example;\n";

const meta = {
  component: Badge,
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nRender a badge or give another element the appearance of a badge.\n\n**Import:** `@/registry/erbium/ui/badge`\n\n## Usage\n\n```tsx\nimport { Badge } from \"@/registry/erbium/ui/badge\";\n```\n\n```tsx\n<Badge variant=\"default | outline | secondary | info | success | warning | error | ghost-error | ghost-info | ghost-success | ghost-warning | tag-gray | tag-red | tag-orange | tag-yellow | tag-green | tag-cyan | tag-blue | tag-purple | tag-magenta\">\n  Badge\n</Badge>\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [mergeProps](https://base-ui.com/react/utils/merge-props)\n- [useRender](https://base-ui.com/react/utils/use-render)",
      },
    },
  },
} satisfies Meta<typeof Badge>;

export default { ...meta, title: "Components/Badge",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Badge> = {
  args: { variant: "default", children: "Badge", className: "" },
  argTypes: {
    variant: {
      control: "select",
      options: [
        "default",
        "secondary",
        "info",
        "success",
        "warning",
        "error",
        "ghost-error",
        "ghost-success",
        "ghost-warning",
        "ghost-info",
        "tag-gray",
        "tag-red",
        "tag-orange",
        "tag-yellow",
        "tag-green",
        "tag-cyan",
        "tag-blue",
        "tag-purple",
        "tag-magenta",
        "outline",
        "ghost",
        "link",
      ],
    },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Variants: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `variant` prop to change the variant of the badge." },
      source: { code: VariantsSource },
    },
  },
  render: VariantsExample,
};

export const Link: Story = {
  parameters: {
    docs: {
      description: { story: "Use the `render` prop to render a link as a badge." },
      source: { code: LinkSource },
    },
  },
  render: LinkExample,
};

export const WithIcon: Story = {
  parameters: {
    docs: {
      description: { story: "You can render an icon inside the badge. Use `data-icon=\"inline-start\"` to render the icon on the left and `data-icon=\"inline-end\"` to render the icon on the right." },
      source: { code: WithIconSource },
    },
  },
  render: WithIconExample,
};

export const WithSpinner: Story = {
  parameters: {
    docs: {
      description: { story: "You can render a spinner inside the badge. Remember to add the `data-icon=\"inline-start\"` or `data-icon=\"inline-end\"` prop to the spinner." },
      source: { code: WithSpinnerSource },
    },
  },
  render: WithSpinnerExample,
};

import { HugeiconsIcon } from "@hugeicons/react";
import Bookmark01Icon from "@hugeicons/core-free-icons/Bookmark01Icon";

import { Badge } from "@/registry/erbium/ui/badge";

export function BadgeWithIconLeft() {
  return (
    <div className="flex flex-wrap gap-related">
      <Badge variant="success" statusIcon>
        Verified
      </Badge>
      <Badge variant="outline">
        Bookmark
        <HugeiconsIcon icon={Bookmark01Icon} data-icon="inline-end" />
      </Badge>
    </div>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import ArrowUpRight01Icon from "@hugeicons/core-free-icons/ArrowUpRight01Icon";

import { Badge } from "@/registry/erbium/ui/badge";

export function BadgeAsLink() {
  return (
    <Badge render={<a href="#link" />}>
      Open Link <HugeiconsIcon icon={ArrowUpRight01Icon} data-icon="inline-end" />
    </Badge>
  );
}

import { Badge } from "@/registry/erbium/ui/badge";
import { Spinner } from "@/registry/erbium/ui/spinner";

export function BadgeWithSpinner() {
  return (
    <div className="flex flex-wrap gap-related">
      <Badge variant="error">
        <Spinner data-icon="inline-start" />
        Deleting
      </Badge>
      <Badge variant="secondary">
        Generating
        <Spinner data-icon="inline-end" />
      </Badge>
    </div>
  );
}

